import struct,glob,os
def dims(p):
    b=open(p,'rb').read(40)
    f=b[12:16]
    if f==b'VP8X': w=1+int.from_bytes(b[24:27],'little'); h=1+int.from_bytes(b[27:30],'little')
    elif f==b'VP8L':
        v=int.from_bytes(b[21:25],'little'); w=(v&0x3FFF)+1; h=((v>>14)&0x3FFF)+1
    else: w,h=struct.unpack('<HH',b[26:30]); w&=0x3fff; h&=0x3fff
    return w,h
for p in sorted(glob.glob('*.webp')): print(p, dims(p), os.path.getsize(p)//1024,'KB')
